Employee = globals().get('Employee')
if not Employee:
    raise AssertionError('Step 1: Employee class not defined')

# Check initial employee_count (before instances created in student code)
# Note: student code creates 3 instances, so count should be 3
if Employee.employee_count != 3:
    raise AssertionError(f'Step 3: employee_count should be 3 after creating three instances, got {Employee.employee_count}')

# Check instances have correct attributes
for var in ['emp1', 'emp2', 'emp3']:
    if var not in globals():
        raise AssertionError(f'Step 6: {var} variable not found')
    obj = globals()[var]
    if not isinstance(obj, Employee):
        raise AssertionError(f'Step 6: {var} should be an Employee instance')
    if not hasattr(obj, 'name') or not hasattr(obj, 'salary'):
        raise AssertionError(f'Step 3: {var} missing name or salary attribute')

# Check specific values
if globals()['emp1'].name != 'Dewey' or globals()['emp1'].salary != 50000:
    raise AssertionError('Step 6: emp1 should be Dewey with salary 50000')
if globals()['emp2'].name != 'Huey' or globals()['emp2'].salary != 60000:
    raise AssertionError('Step 6: emp2 should be Huey with salary 60000')
if globals()['emp3'].name != 'Louie' or globals()['emp3'].salary != 55000:
    raise AssertionError('Step 6: emp3 should be Louie with salary 55000')

print('TEST_PASSED')

Employee = globals().get('Employee')
if not Employee:
    raise AssertionError('Step 1: Employee class not defined')

# Check validate_salary exists and works
if not hasattr(Employee, 'validate_salary'):
    raise AssertionError('Step 4: validate_salary static method not found')

if not callable(Employee.validate_salary):
    raise AssertionError('Step 4: validate_salary should be callable')

if not Employee.validate_salary(50000):
    raise AssertionError('Step 4: validate_salary(50000) should return True')
if Employee.validate_salary(-100):
    raise AssertionError('Step 4: validate_salary(-100) should return False')
if Employee.validate_salary(0):
    raise AssertionError('Step 4: validate_salary(0) should return False')

# Check company_policy exists and works
if not hasattr(Employee, 'company_policy'):
    raise AssertionError('Step 5: company_policy static method not found')

if not callable(Employee.company_policy):
    raise AssertionError('Step 5: company_policy should be callable')

policy = Employee.company_policy()
if policy != 'Silent Running!':
    raise AssertionError(f'Step 5: company_policy should return "Silent Running!", got "{policy}"')

